157	    /**
158	     * Fixed city-to-region lookup backing {@link #getLocality()}. Cities absent from this
159	     * table derive the locality {@code "UNKNOWN"}.
160	     */
161	    private static final Map<String, String> CITY_REGIONS =
162	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
